CREATE TABLE cleaned_measurements AS
SELECT * FROM measurements
WHERE cognitive_score < (
    SELECT AVG(cognitive_score) - 2 * (
        SELECT sqrt(
            AVG(cognitive_score * cognitive_score) - AVG(cognitive_score) * AVG(cognitive_score)
        ) FROM measurements
    )
) OR cognitive_score > (
    SELECT AVG(cognitive_score) + 2 * (
        SELECT sqrt(
            AVG(cognitive_score * cognitive_score) - AVG(cognitive_score) * AVG(cognitive_score)
        ) FROM measurements
    )
) OR reaction_ms < (
    SELECT AVG(reaction_ms) - 2 * (
        SELECT sqrt(
            AVG(reaction_ms * reaction_ms) - AVG(reaction_ms) * AVG(reaction_ms)
        ) FROM measurements
    )
) OR reaction_ms > (
    SELECT AVG(reaction_ms) + 2 * (
        SELECT sqrt(
            AVG(reaction_ms * reaction_ms) - AVG(reaction_ms) * AVG(reaction_ms)
        ) FROM measurements
    )
)
